{
  "instrument": "Regulation (EU) 2023/1115 — IHK guidance on deadlines for micro and small enterprises",
  "jurisdiction": "EU",
  "summary": "Work out your size class from turnover, balance sheet and headcount now: micro and small enterprises must meet the EUDR duties from 30 June 2026, all other traders from 30 December 2025. This IHK page explains the deadlines of Regulation (EU) 2023/1115 for companies placing covered products on the EU market.",
  "effective_dates": [
    "2025-12-30",
    "2026-06-30"
  ],
  "obligations": [
    {
      "text": "Meet the EUDR duties from 30 June 2026 if you are a micro or small enterprise.",
      "quote": "Kleinst- und Kleinunternehmen müssen die Pflichten erst ab dem 30. Juni 2026 erfüllen."
    },
    {
      "text": "Submit due diligence statements from 30 December 2025 if you are not an SME.",
      "quote": "Händler, die keine KMU sind, müssen ab dem 30. Dezember 2025 Sorgfaltserklärungen abgeben."
    }
  ]
}

